import socket, threading, requests
from unittest import mock
from billing import invoices as inv
from urllib3.connectionpool import HTTPConnectionPool
inv._ledger.mount("http://", inv._ledger.get_adapter("https://"))
calls = {"n": 0}
orig = HTTPConnectionPool._new_conn
def counting(self):
    calls["n"] += 1
    return orig(self)
with mock.patch.object(HTTPConnectionPool, "_new_conn", counting), mock.patch.object(inv, "LEDGER_URL", "http://127.0.0.1:1/"):
    try: inv.finalize(inv.Invoice("i1", "c1", 100))
    except requests.ConnectionError: pass
print("connect-refused attempts:", calls["n"])
s = socket.socket(); s.bind(("127.0.0.1", 0)); s.listen(5); port = s.getsockname()[1]
hits = []
def srv():
    while True:
        c, _ = s.accept(); hits.append(c)
threading.Thread(target=srv, daemon=True).start()
real_post = inv._ledger.post
with mock.patch.object(inv, "LEDGER_URL", f"http://127.0.0.1:{port}/"), \
     mock.patch.object(inv._ledger, "post", lambda *a, **k: real_post(*a, **{**k, "timeout": 0.5})):
    try: inv.finalize(inv.Invoice("i2", "c1", 100))
    except requests.exceptions.ReadTimeout: pass
print("read-timeout requests sent:", len(hits))
EOF",
 "description": "Verify retry behavior with stubbed structlog"
}

